def find_prime_pairs(sum_val):
    pairs = []
    # q must be prime and q < sum_val / 2
    for q in range(3, sum_val // 2):
        if is_prime(q):
            r = sum_val - q
            if is_prime(r) and r > q:
                pairs.append((q, r))
    return pairs

