def investigate_case3(pairs):
    results = {}
    for p, r in pairs:
        # Determine the range for q: p < q < r
        # We need a list of primes between p and r

        # Optimization: Check constraints 1 and 2 first, as they only depend on q
        # P4 = 800 + q must be prime
        # P3 = 800 - q must be prime

        # Find all primes q in (p, r)
        q_candidates = []
        for q in range(p + 1, r):
            if is_prime(q):
                # Check Constraints 1 and 2
                if is_prime(800 + q) and is_prime(800 - q):
                    q_candidates.append(q)

        valid_q_results = []
        for q in q_candidates:
            # Check Constraints 3 and 4
            P1 = 2 * p + q - 800
            P2 = q + 800 - 2 * p
            P3 = 800 - q  # Already checked
            P4 = 800 + q  # Already checked

            if is_prime(P1) and is_prime(P2):
                valid_q_results.append(q)

        results[(p, r)] = valid_q_results

    return results

