def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

primes = [p for p in range(2, 801) if is_prime(p)]

q_r_pairs = []
for q in primes:
    r = 800 - q
    if r > q and is_prime(r):
        q_r_pairs.append((q, r))

print(f"Total pairs (q, r): {len(q_r_pairs)}")
print("All pairs (q, r):")
