max_r = 0

for q, r in q_r_pairs:
    # Constraints on p: p < q, p is prime
    # Also, 800-p and 800+p must be prime

    potential_p = []
    for p in primes:
        if p >= q:
            break

        if p == 2:
            # 800-2 = 798 (not prime). Since p must be odd (as q, r are odd, and 800 +/- p must be odd primes unless one is 2), p=2 is unlikely to work unless 800+/-p results in 2, which is impossible.
            # Since q and r are odd (q+r=800), p must be odd for 800 +/- p to be odd primes.
            continue

        if is_prime(800 - p) and is_prime(800 + p):
            potential_p.append(p)

    # Filter potential p based on the remaining constraints
    for p in potential_p:
        # A = 2q - 800
